import 'dart:convert';
import 'dart:io';

import 'package:bibblebob/link/link_codec.dart';
import 'package:bibblebob/models/card_content.dart';
import 'package:flutter_test/flutter_test.dart';

import 'helpers.dart';

/// The app's codec must produce exactly what the website's codec produces
/// (shared/link-vectors.json is generated by tools/test-linkcodec.mjs).
void main() {
  final spec = loadSpec();
  final codec = LinkCodec(spec);
  final vectors = (jsonDecode(File('../shared/link-vectors.json').readAsStringSync()) as List)
      .cast<Map<String, dynamic>>();

  CardContent fromVector(Map<String, dynamic> c) {
    final own = c['type'] == 'links';
    final links = [
      for (final l in (c['links'] as List).cast<Map<String, dynamic>>())
        CardLink(label: l['label'] as String, url: l['url'] as String, icon: (l['icon'] ?? 'link') as String),
    ];
    var content = CardContent.empty(spec).copyWith(
      useOwnLink: own,
      name: c['name'] as String,
      title: (c['title'] ?? '') as String,
      business: (c['business'] ?? '') as String,
      phone: (c['phone'] ?? '') as String,
      email: (c['email'] ?? '') as String,
      description: (c['description'] ?? '') as String,
      singleLinkMode: c['singleLinkMode'] == 'redirect' ? SingleLinkMode.redirect : SingleLinkMode.page,
    );
    content = own ? content.copyWith(ownLinks: links) : content.copyWith(links: links);
    if (!own) {
      final st = c['style'] as Map<String, dynamic>;
      content = content.copyWith(
        templateId: c['templateId'] as String,
        style: CardStyle(
          bg: st['bg'] as String,
          text: st['text'] as String,
          accent: st['accent'] as String,
          fontId: st['fontId'] as String,
        ),
      );
    }
    return content;
  }

  for (final v in vectors) {
    test('encode matches website: ${v['name']}', () {
      final card = v['card'] as Map<String, dynamic>;
      final enc = codec.encode(fromVector(card), card['id'] as String, maxBytes: v['maxBytes'] as int?);
      expect(enc.payload, v['payload']);
      expect(enc.bytes, v['bytes']);
      expect(enc.omitted, (v['omitted'] as List).cast<String>());
    });

    test('decode matches website: ${v['name']}', () {
      final want = v['decoded'] as Map<String, dynamic>;
      final got = codec.decode(v['payload'] as String)!;
      final c = got.content;
      expect(got.id, want['id']);
      expect(c.useOwnLink, want['type'] == 'links');
      expect(c.name, want['name']);
      expect(c.title, want['title'] ?? '');
      expect(c.business, want['business'] ?? '');
      expect(c.phone, want['phone'] ?? '');
      expect(c.email, want['email'] ?? '');
      expect(c.description, want['description'] ?? '');
      final links = c.useOwnLink ? c.ownLinks : c.links;
      final wantLinks = (want['links'] as List).cast<Map<String, dynamic>>();
      expect(links.map((l) => [l.label, l.url]).toList(), wantLinks.map((l) => [l['label'], l['url']]).toList());
      if (!c.useOwnLink) {
        expect(links.map((l) => l.icon).toList(), wantLinks.map((l) => l['icon']).toList());
        final st = want['style'] as Map<String, dynamic>;
        expect(
          [c.templateId, c.style.bg, c.style.text, c.style.accent, c.style.fontId],
          [want['templateId'], st['bg'], st['text'], st['accent'], st['fontId']],
        );
      } else {
        expect(c.singleLinkMode.name, want['singleLinkMode']);
      }
    });
  }

  test('tag capacity matches the website', () {
    expect(codec.tagCapacity(137), 82);
    expect(codec.tagCapacity(496), 349);
    expect(codec.tagCapacity(868), 628);
  });

  test('full link round-trips through decodeLink', () {
    final content = CardContent.empty(spec).copyWith(name: 'Ada', email: 'ada@example.com');
    final link = Uri.parse(codec.link(content, 'abcdef'));
    expect(link.toString(), startsWith('https://bibblebob.pages.dev/c#'));
    final back = codec.decodeLink(link)!;
    expect(back.id, 'abcdef');
    expect(back.content.email, 'ada@example.com');
    expect(codec.decodeLink(Uri.parse('https://evil.example/c#${link.fragment}')), isNull);
    expect(codec.decodeLink(Uri.parse('https://bibblebob.pages.dev/c#garbage!!')), isNull);
    expect(codec.decodeLink(Uri.parse('https://bibblebob.pages.dev/')), isNull);
  });

  test('own-link cards put their main link straight on the tag', () {
    final card = CardContent.empty(spec).copyWith(
      useOwnLink: true,
      name: 'Grace',
      ownLinks: const [
        CardLink(label: 'Linktree', url: 'https://linktr.ee/grace'),
        CardLink(label: 'Blog', url: 'https://grace.dev'),
      ],
    );
    expect(codec.tagLink(card, 'abcdef').url, 'https://linktr.ee/grace');
    expect(codec.link(card, 'abcdef'), 'https://linktr.ee/grace');
    // Template cards still travel inside a bibblebob link.
    final template = CardContent.empty(spec).copyWith(name: 'Ada');
    expect(codec.tagLink(template, 'abcdef').url, startsWith('https://bibblebob.pages.dev/c#'));
  });

  test('binary tag records: capacity, round trip, and record type', () {
    expect(codec.binaryCapacity(137), 116); // NTAG213
    expect(codec.binaryCapacity(496), 472); // NTAG215
    expect(codec.binaryCapacity(868), 844); // NTAG216
    final card = CardContent.empty(spec).copyWith(name: 'Ada', phone: '+44 20 7946 0958', templateId: 'bold');
    final enc = codec.encode(card, 'a1b2c3', maxBytes: codec.binaryCapacity(137));
    final back = codec.decodeBytes(enc.raw)!;
    expect(back.id, 'a1b2c3');
    expect(back.content.phone, '+44 20 7946 0958');
    expect(back.content.templateId, 'bold');
    // What MainActivity.kt builds from a tapped tag decodes to the same card.
    final viaLink = codec.decodeLink(Uri.parse('https://bibblebob.pages.dev/c#${enc.payload}'))!;
    expect(viaLink.content.name, 'Ada');
  });
}
